{"command":"cat > /tmp/bench_chacha.c << 'EOF'
#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40 * 1024 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 64);
    unsigned char key[32], nonce[12], aad[32], tag[16];
    memset(pt, 1, n);
    memset(key, 2, 32);
    memset(nonce, 3, 12);
    memset(aad, 4, 32);

    const EVP_CIPHER *cipher = EVP_chacha20_poly1305();
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // warmup
    int outlen = 0, total = 0;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
    total = outlen;
    EVP_EncryptFinal_ex(ctx, ct + total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, ct + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("openssl reused ctx: %.4f s/iter  %.1f MB/s  tag0=%02x\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps), tag[0]);

    // new ctx each time
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_CIPHER_CTX *c2 = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(c2, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(c2, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(c2, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(c2, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(c2, ct, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(c2, ct + total, &outlen);
        EVP_CIPHER_CTX_ctrl(c2, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(c2);
    }
    t1 = now();
    printf("openssl new ctx: %.4f s/iter  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    // no aad
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, ct + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("openssl no aad reused: %.4f s/iter  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    return 0;
}
EOF
