{"command":"cat > bench_mt.c << 'EOF'
#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *pt;
    unsigned char *ct;
    size_t n;
    unsigned char key[32];
    unsigned char nonce[12];
    unsigned char aad[32];
    int reps;
} job;

void *worker(void *arg) {
    job *j = arg;
    unsigned char tag[16];
    int outlen = 0, total = 0;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_chacha20_poly1305();
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    for (int i = 0; i < j->reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, j->aad, 32);
        EVP_EncryptUpdate(ctx, j->ct, &outlen, j->pt, (int)j->n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, j->ct + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    int nthreads_list[] = {1, 2, 4, 6, 8, 12};
    size_t n = 40 * 1024 * 1024;
    int reps = 2;
    for (int t = 0; t < 6; t++) {
        int nt = nthreads_list[t];
        pthread_t th[16];
        job jobs[16];
        for (int i = 0; i < nt; i++) {
            jobs[i].pt = malloc(n);
            jobs[i].ct = malloc(n + 64);
            memset(jobs[i].pt, i+1, n);
            memset(jobs[i].key, 2, 32);
            memset(jobs[i].nonce, 3, 12);
            memset(jobs[i].aad, 4, 32);
            jobs[i].n = n;
            jobs[i].reps = reps;
        }
        double t0 = now();
        for (int i = 0; i < nt; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        double t1 = now();
        double per = (t1 - t0) / reps;
        double mbps = (nt * (n / 1e6)) / per;
        printf("threads=%d  wall %.4f s for %d x 40MB   aggregate %.1f MB/s  per-thread-equiv %.1f MB/s\n",
               nt, per, nt, mbps, (n/1e6)/per);
        for (int i = 0; i < nt; i++) { free(jobs[i].pt); free(jobs[i].ct); }
    }
    return 0;
}
EOF
cc -O3 -o bench_mt bench_mt.c -I/usr/local/opt/openssl@3/include -L/usr/local/opt/openssl@3/lib -lcrypto -lpthread && ./bench_mt"}

{"command":"cat > bench_vec.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <immintrin.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static inline uint32_t rotl(uint32_t x, int n) { return (x << n) | (x >> (32 - n)); }

static inline void quarterround(uint32_t *a, uint32_t *b, uint32_t *c, uint32_t *d) {
    *a += *b; *d ^= *a; *d = rotl(*d, 16);
    *c += *d; *b ^= *c; *b = rotl(*b, 12);
    *a += *b; *d ^= *a; *d = rotl(*d, 8);
    *c += *d; *b ^= *c; *b = rotl(*b, 7);
}

/* 4-way AVX2 ChaCha20 block */
static inline __m256i rotl_avx(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static void chacha20_xor_avx2(unsigned char *out, const unsigned char *in, size_t len,
                               const uint32_t key[8], const uint32_t counter, const uint32_t nonce[3]) {
    size_t off = 0;
    uint32_t ctr = counter;
    while (off + 256 <= len) {
        __m256i x0 = _mm256_set1_epi32(0x61707865);
        __m256i x1 = _mm256_set1_epi32(0x3320646e);
        __m256i x2 = _mm256_set1_epi32(0x79622d32);
        __m256i x3 = _mm256_set1_epi32(0x6b206574);
        __m256i x4 = _mm256_set1_epi32(key[0]);
        __m256i x5 = _mm256_set1_epi32(key[1]);
        __m256i x6 = _mm256_set1_epi32(key[2]);
        __m256i x7 = _mm256_set1_epi32(key[3]);
        __m256i x8 = _mm256_set1_epi32(key[4]);
        __m256i x9 = _mm256_set1_epi32(key[5]);
        __m256i x10 = _mm256_set1_epi32(key[6]);
        __m256i x11 = _mm256_set1_epi32(key[7]);
        __m256i x12 = _mm256_setr_epi32(ctr, ctr+1, ctr+2, ctr+3, ctr+4, ctr+5, ctr+6, ctr+7);
        __m256i x13 = _mm256_set1_epi32(nonce[0]);
        __m256i x14 = _mm256_set1_epi32(nonce[1]);
        __m256i x15 = _mm256_set1_epi32(nonce[2]);

        __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
        __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

        for (int i = 0; i < 10; i++) {
            /* column rounds */
            x0 = _mm256_add_epi32(x0, x4); x12 = rotl_avx(_mm256_xor_si256(x12, x0), 16);
            x8 = _mm256_add_epi32(x8, x12); x4 = rotl_avx(_mm256_xor_si256(x4, x8), 12);
            x0 = _mm256_add_epi32(x0, x4); x12 = rotl_avx(_mm256_xor_si256(x12, x0), 8);
            x8 = _mm256_add_epi32(x8, x12); x4 = rotl_avx(_mm256_xor_si256(x4, x8), 7);

            x1 = _mm256_add_epi32(x1, x5); x13 = rotl_avx(_mm256_xor_si256(x13, x1), 16);
            x9 = _mm256_add_epi32(x9, x13); x5 = rotl_avx(_mm256_xor_si256(x5, x9), 12);
            x1 = _mm256_add_epi32(x1, x5); x13 = rotl_avx(_mm256_xor_si256(x13, x1), 8);
            x9 = _mm256_add_epi32(x9, x13); x5 = rotl_avx(_mm256_xor_si256(x5, x9), 7);

            x2 = _mm256_add_epi32(x2, x6); x14 = rotl_avx(_mm256_xor_si256(x14, x2), 16);
            x10 = _mm256_add_epi32(x10, x14); x6 = rotl_avx(_mm256_xor_si256(x6, x10), 12);
            x2 = _mm256_add_epi32(x2, x6); x14 = rotl_avx(_mm256_xor_si256(x14, x2), 8);
            x10 = _mm256_add_epi32(x10, x14); x6 = rotl_avx(_mm256_xor_si256(x6, x10), 7);

            x3 = _mm256_add_epi32(x3, x7); x15 = rotl_avx(_mm256_xor_si256(x15, x3), 16);
            x11 = _mm256_add_epi32(x11, x15); x7 = rotl_avx(_mm256_xor_si256(x7, x11), 12);
            x3 = _mm256_add_epi32(x3, x7); x15 = rotl_avx(_mm256_xor_si256(x15, x3), 8);
            x11 = _mm256_add_epi32(x11, x15); x7 = rotl_avx(_mm256_xor_si256(x7, x11), 7);

            /* diagonal rounds */
            x0 = _mm256_add_epi32(x0, x5); x15 = rotl_avx(_mm256_xor_si256(x15, x0), 16);
            x10 = _mm256_add_epi32(x10, x15); x5 = rotl_avx(_mm256_xor_si256(x5, x10), 12);
            x0 = _mm256_add_epi32(x0, x5); x15 = rotl_avx(_mm256_xor_si256(x15, x0), 8);
            x10 = _mm256_add_epi32(x10, x15); x5 = rotl_avx(_mm256_xor_si256(x5, x10), 7);

            x1 = _mm256_add_epi32(x1, x6); x12 = rotl_avx(_mm256_xor_si256(x12, x1), 16);
            x11 = _mm256_add_epi32(x11, x12); x6 = rotl_avx(_mm256_xor_si256(x6, x11), 12);
            x1 = _mm256_add_epi32(x1, x6); x12 = rotl_avx(_mm256_xor_si256(x12, x1), 8);
            x11 = _mm256_add_epi32(x11, x12); x6 = rotl_avx(_mm256_xor_si256(x6, x11), 7);

            x2 = _mm256_add_epi32(x2, x7); x13 = rotl_avx(_mm256_xor_si256(x13, x2), 16);
            x8 = _mm256_add_epi32(x8, x13); x7 = rotl_avx(_mm256_xor_si256(x7, x8), 12);
            x2 = _mm256_add_epi32(x2, x7); x13 = rotl_avx(_mm256_xor_si256(x13, x2), 8);
            x8 = _mm256_add_epi32(x8, x13); x7 = rotl_avx(_mm256_xor_si256(x7, x8), 7);

            x3 = _mm256_add_epi32(x3, x4); x14 = rotl_avx(_mm256_xor_si256(x14, x3), 16);
            x9 = _mm256_add_epi32(x9, x14); x4 = rotl_avx(_mm256_xor_si256(x4, x9), 12);
            x3 = _mm256_add_epi32(x3, x4); x14 = rotl_avx(_mm256_xor_si256(x14, x3), 8);
            x9 = _mm256_add_epi32(x9, x14); x4 = rotl_avx(_mm256_xor_si256(x4, x9), 7);
        }

        x0 = _mm256_add_epi32(x0, s0);
        x1 = _mm256_add_epi32(x1, s1);
        x2 = _mm256_add_epi32(x2, s2);
        x3 = _mm256_add_epi32(x3, s3);
        x4 = _mm256_add_epi32(x4, s4);
        x5 = _mm256_add_epi32(x5, s5);
        x6 = _mm256_add_epi32(x6, s6);
        x7 = _mm256_add_epi32(x7, s7);
        x8 = _mm256_add_epi32(x8, s8);
        x9 = _mm256_add_epi32(x9, s9);
        x10 = _mm256_add_epi32(x10, s10);
        x11 = _mm256_add_epi32(x11, s11);
        x12 = _mm256_add_epi32(x12, s12);
        x13 = _mm256_add_epi32(x13, s13);
        x14 = _mm256_add_epi32(x14, s14);
        x15 = _mm256_add_epi32(x15, s15);

        /* transpose 8 blocks of 16 words into sequential output. Each block is 64 bytes.
           words are interleaved across 8 lanes. We'll store lane-wise by extracting. */
        uint32_t b0[8], b1[8], b2[8], b3[8], b4[8], b5[8], b6[8], b7[8];
        uint32_t b8[8], b9[8], b10[8], b11[8], b12[8], b13[8], b14[8], b15[8];
        _mm256_storeu_si256((__m256i*)b0, x0);
        _mm256_storeu_si256((__m256i*)b1, x1);
        _mm256_storeu_si256((__m256i*)b2, x2);
        _mm256_storeu_si256((__m256i*)b3, x3);
        _mm256_storeu_si256((__m256i*)b4, x4);
        _mm256_storeu_si256((__m256i*)b5, x5);
        _mm256_storeu_si256((__m256i*)b6, x6);
        _mm256_storeu_si256((__m256i*)b7, x7);
        _mm256_storeu_si256((__m256i*)b8, x8);
        _mm256_storeu_si256((__m256i*)b9, x9);
        _mm256_storeu_si256((__m256i*)b10, x10);
        _mm256_storeu_si256((__m256i*)b11, x11);
        _mm256_storeu_si256((__m256i*)b12, x12);
        _mm256_storeu_si256((__m256i*)b13, x13);
        _mm256_storeu_si256((__m256i*)b14, x14);
        _mm256_storeu_si256((__m256i*)b15, x15);

        uint32_t *lanes[16] = {b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15};
        for (int lane = 0; lane < 8; lane++) {
            uint32_t block[16];
            for (int w = 0; w < 16; w++) block[w] = lanes[w][lane];
            const uint32_t *src = (const uint32_t *)(in + off + lane * 64);
            uint32_t *dst = (uint32_t *)(out + off + lane * 64);
            for (int w = 0; w < 16; w++) dst[w] = src[w] ^ block[w];
        }
        off += 256;
        ctr += 8;
    }
    /* scalar tail */
    while (off < len) {
        uint32_t s[16] = {
            0x61707865, 0x3320646e, 0x79622d32, 0x6b206574,
            key[0], key[1], key[2], key[3], key[4], key[5], key[6], key[7],
            ctr, nonce[0], nonce[1], nonce[2]
        };
        uint32_t x[16];
        memcpy(x, s, sizeof x);
        for (int i = 0; i < 10; i++) {
            quarterround(&x[0], &x[4], &x[8], &x[12]);
            quarterround(&x[1], &x[5], &x[9], &x[13]);
            quarterround(&x[2], &x[6], &x[10], &x[14]);
            quarterround(&x[3], &x[7], &x[11], &x[15]);
            quarterround(&x[0], &x[5], &x[10], &x[15]);
            quarterround(&x[1], &x[6], &x[11], &x[12]);
            quarterround(&x[2], &x[7], &x[8], &x[13]);
            quarterround(&x[3], &x[4], &x[9], &x[14]);
        }
        for (int i = 0; i < 16; i++) x[i] += s[i];
        size_t chunk = len - off; if (chunk > 64) chunk = 64;
        unsigned char ks[64];
        memcpy(ks, x, 64);
        for (size_t i = 0; i < chunk; i++) out[off + i] = in[off + i] ^ ks[i];
        off += chunk;
        ctr++;
    }
}

int main() {
    size_t n = 40 * 1024 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *ct2 = malloc(n + 64);
    memset(pt, 0x5a, n);
    uint32_t key[8];
    uint32_t nonce[3];
    for (int i = 0; i < 8; i++) key[i] = 0x01020304u * (i+1);
    nonce[0] = 0x11111111; nonce[1] = 0x22222222; nonce[2] = 0x33333333;

    /* warmup */
    chacha20_xor_avx2(ct, pt, n, key, 1, nonce);

    int reps = 3;
    double t0 = now();
    for (int i = 0; i < reps; i++) chacha20_xor_avx2(ct, pt, n, key, 1, nonce);
    double t1 = now();
    printf("naive avx2 8-way: %.4f s/iter  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* openssl chacha20 only for comparison */
    unsigned char keyb[32], iv[16];
    memcpy(keyb, key, 32);
    memset(iv, 0, 16);
    /* OpenSSL ChaCha20 IV is 16 bytes: 4 byte counter + 12 byte nonce, little endian */
    memcpy(iv, &((uint32_t){1}), 4);
    memcpy(iv+4, nonce, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, keyb, iv);
    EVP_EncryptUpdate(ctx, ct2, &outlen, pt, (int)n);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, iv);
        EVP_EncryptUpdate(ctx, ct2, &outlen, pt, (int)n);
    }
    t1 = now();
    printf("openssl chacha20: %.4f s/iter  %.1f MB/s  match=%d\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps), memcmp(ct, ct2, n)==0);
    return 0;
}
EOF
