#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *pt;
    unsigned char *ct;
    size_t off, len;
    unsigned char key[32];
    unsigned char iv[16]; /* 4 byte counter LE + 12 byte nonce */
    uint32_t counter;
} job;

void *worker(void *arg) {
    job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    /* set counter in iv */
    uint32_t ctr = j->counter;
    memcpy(j->iv, &ctr, 4);
    int outlen = 0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, j->key, j->iv);
    EVP_EncryptUpdate(ctx, j->ct + j->off, &outlen, j->pt + j->off, (int)j->len);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    size_t n = 40ull * 1024 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *ctref = malloc(n);
    memset(pt, 0xab, n);
    unsigned char key[32], nonce[12];
    memset(key, 0x11, 32);
    memset(nonce, 0x22, 12);

    int nthreads_list[] = {1,2,4,6};
    int reps = 3;
    for (int ti = 0; ti < 4; ti++) {
        int nt = nthreads_list[ti];
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            pthread_t th[16];
            job jobs[16];
            size_t chunk = (n / 64 / nt) * 64;
            for (int i = 0; i < nt; i++) {
                jobs[i].pt = pt;
                jobs[i].ct = ct;
                jobs[i].off = i * chunk;
                jobs[i].len = (i == nt-1) ? (n - jobs[i].off) : chunk;
                memcpy(jobs[i].key, key, 32);
                memset(jobs[i].iv, 0, 16);
                memcpy(jobs[i].iv + 4, nonce, 12);
                jobs[i].counter = 1 + (uint32_t)(jobs[i].off / 64);
                pthread_create(&th[i], NULL, worker, &jobs[i]);
            }
            for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        }
        double t1 = now();
        printf("threads=%d  %.4f s/iter  %.1f MB/s\n", nt, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    }
    /* verify vs single thread openssl */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[16];
    uint32_t ctr = 1;
    memcpy(iv, &ctr, 4);
    memcpy(iv+4, nonce, 12);
    int outlen;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ctref, &outlen, pt, (int)n);
    printf("match last ct vs ref: %d\n", memcmp(ct, ctref, n)==0);
    return 0;
}
EOF
