    chacha_poly1305_set_nonce(&actx, nonce);
    chacha_poly1305_update(&actx, 32, aad);
    chacha_poly1305_encrypt(&actx, n, ct, pt);
    chacha_poly1305_digest(&actx, 16, digest);

    t0 = now();
    for (int i = 0; i < reps; i++) {
