#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                            const unsigned int key[8], const unsigned int counter[4]);
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void *xmalloc(size_t n) {
    void *p = NULL;
    posix_memalign(&p, 64, n);
    memset(p, 0x5a, n); /* fault pages */
    return p;
}

typedef struct {
    unsigned char *pt, *ct;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter0;
    unsigned int nonce[3];
} job;

void *chacha_worker(void *arg) {
    job *j = arg;
    unsigned int ctr[4] = { j->counter0 + (unsigned int)(j->off / 64), j->nonce[0], j->nonce[1], j->nonce[2] };
    ChaCha20_ctr32(j->ct + j->off, j->pt + j->off, j->len, j->key, ctr);
    return NULL;
}

int main() {
    size_t n = 40ull * 1024 * 1024;
    unsigned char *pt = xmalloc(n);
    unsigned char *ct = xmalloc(n);
    unsigned char *extra = xmalloc(n);
    printf("allocated\n");

    int reps = 3;
    double t0 = now();
    for (int i = 0; i < reps; i++) memcpy(extra, pt, n);
    double t1 = now();
    printf("memcpy dirty: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    volatile unsigned long long sink = 0;
    t0 = now();
    for (int i = 0; i < reps; i++) {
        unsigned long long s = 0;
        unsigned long long *p = (unsigned long long*)pt;
        size_t c = n / 8;
        for (size_t j = 0; j < c; j += 8)
            s += p[j]+p[j+1]+p[j+2]+p[j+3]+p[j+4]+p[j+5]+p[j+6]+p[j+7];
        sink += s;
    }
    t1 = now();
    printf("read: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    unsigned int key[8] = {1,2,3,4,5,6,7,8};
    unsigned int counter[4] = {1,9,10,11};
    t0 = now();
    for (int i = 0; i < reps; i++) ChaCha20_ctr32(ct, pt, n, key, counter);
    t1 = now();
    printf("chacha1: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    int nts[] = {2,4,6,8};
    for (int ti = 0; ti < 4; ti++) {
        int nt = nts[ti];
        t0 = now();
        for (int r = 0; r < reps; r++) {
            pthread_t th[16];
            job jobs[16];
            size_t blocks = n/64;
            size_t bper = blocks / nt;
            for (int i = 0; i < nt; i++) {
                jobs[i].pt = pt; jobs[i].ct = ct;
                jobs[i].off = i * bper * 64;
                size_t bend = (i==nt-1)? blocks : (i+1)*bper;
                jobs[i].len = bend*64 - jobs[i].off;
                memcpy(jobs[i].key, key, 32);
                jobs[i].counter0 = 1;
                jobs[i].nonce[0]=9; jobs[i].nonce[1]=10; jobs[i].nonce[2]=11;
                pthread_create(&th[i], NULL, chacha_worker, &jobs[i]);
            }
            for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        }
        t1 = now();
        printf("chacha threads=%d %.4f s  %.1f MB/s\n", nt, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    }

    void *pctx = malloc(Poly1305_ctx_size());
    unsigned char pkey[32]; memset(pkey, 7, 32);
    unsigned char mac[16];
    t0 = now();
    for (int i = 0; i < reps; i++) {
        Poly1305_Init(pctx, pkey);
        Poly1305_Update(pctx, ct, n);
        Poly1305_Final(pctx, mac);
    }
    t1 = now();
    printf("poly on ct: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* combined sequential */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        ChaCha20_ctr32(ct, pt, n, key, counter);
        Poly1305_Init(pctx, pkey);
        Poly1305_Update(pctx, ct, n);
        Poly1305_Final(pctx, mac);
    }
    t1 = now();
    printf("seq chacha+poly: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    return 0;
}
