#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                            const unsigned int key[8], const unsigned int counter[4]);
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

static void pad16(void *ctx, size_t n) {
    static const unsigned char zeros[16] = {0};
    size_t rem = n & 15;
    if (rem) Poly1305_Update(ctx, zeros, 16 - rem);
}

static void le64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (unsigned char)(v >> (8*i));
}

/* RFC 8439 AEAD encrypt. out must be len bytes. tag 16 bytes. */
static void aead_encrypt(const unsigned char keyb[32], const unsigned char nonce[12],
                         const unsigned char *aad, size_t aad_len,
                         const unsigned char *pt, size_t pt_len,
                         unsigned char *ct, unsigned char tag[16]) {
    unsigned int key[8];
    memcpy(key, keyb, 32);
    unsigned int counter[4];
    counter[0] = 0;
    memcpy(&counter[1], nonce, 12);

    unsigned char poly_key[64];
    unsigned char zeros64[64] = {0};
    ChaCha20_ctr32(poly_key, zeros64, 64, key, counter);

    counter[0] = 1;
    ChaCha20_ctr32(ct, pt, pt_len, key, counter);

    void *pctx = malloc(Poly1305_ctx_size());
    Poly1305_Init(pctx, poly_key);
    if (aad && aad_len) Poly1305_Update(pctx, aad, aad_len);
    pad16(pctx, aad_len);
    if (pt_len) Poly1305_Update(pctx, ct, pt_len);
    pad16(pctx, pt_len);
    unsigned char lens[16];
    le64(lens, aad_len);
    le64(lens+8, pt_len);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
    free(pctx);
}

static void hexprint(const unsigned char *p, size_t n) {
    for (size_t i = 0; i < n; i++) printf("%02x", p[i]);
    printf("\n");
}

int main() {
    /* RFC 8439 2.8.2 */
    unsigned char key[32] = {
        0x80,0x81,0x82,0x83,0x84,0x85,0x86,0x87,0x88,0x89,0x8a,0x8b,0x8c,0x8d,0x8e,0x8f,
        0x90,0x91,0x92,0x93,0x94,0x95,0x96,0x97,0x98,0x99,0x9a,0x9b,0x9c,0x9d,0x9e,0x9f
    };
    unsigned char nonce[12] = {0x07,0x00,0x00,0x00,0x40,0x41,0x42,0x43,0x44,0x45,0x46,0x47};
    unsigned char aad[12] = {0x50,0x51,0x52,0x53,0xc0,0xc1,0xc2,0xc3,0xc4,0xc5,0xc6,0xc7};
    const char *pt =
        "Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunscreen would be it.";
    size_t n = strlen(pt);
    unsigned char ct[256], tag[16];
    aead_encrypt(key, nonce, aad, 12, (unsigned char*)pt, n, ct, tag);
    printf("ct: "); hexprint(ct, n);
    printf("tag: "); hexprint(tag, 16);
    printf("expected tag: 1ae10b594f09e26a7e902ecbd0600691\n");

    /* compare with EVP AEAD */
    unsigned char out[512];
    int outlen=0, tmplen=0;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
