#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                            const unsigned int key[8], const unsigned int counter[4]);
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define MAX_T 8

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int cmd; /* 0 idle, 1 work, 2 exit */
    unsigned char *pt, *ct;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter0;
    unsigned int nonce[3];
    int ready;
} worker;

static void *worker_fn(void *arg) {
    worker *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd == 2) break;
        unsigned int ctr[4] = {
            w->counter0 + (unsigned int)(w->off / 64),
            w->nonce[0], w->nonce[1], w->nonce[2]
        };
        unsigned char *pt = w->pt, *ct = w->ct;
        size_t off = w->off, len = w->len;
        unsigned int key[8];
        memcpy(key, w->key, 32);
        pthread_mutex_unlock(&w->mu);
        ChaCha20_ctr32(ct + off, pt + off, len, key, ctr);
        pthread_mutex_lock(&w->mu);
        w->cmd = 0;
        w->ready = 1;
        pthread_cond_signal(&w->cv);
    }
    pthread_mutex_unlock(&w->mu);
    return NULL;
}

static worker workers[MAX_T];
static int nthreads = 6;

static void pool_init(int nt) {
    nthreads = nt;
    for (int i = 0; i < nt; i++) {
        pthread_mutex_init(&workers[i].mu, NULL);
        pthread_cond_init(&workers[i].cv, NULL);
        workers[i].cmd = 0;
        workers[i].ready = 0;
        pthread_create(&workers[i].th, NULL, worker_fn, &workers[i]);
    }
}

static void pool_run(unsigned char *pt, unsigned char *ct, size_t n,
                     const unsigned int key[8], unsigned int counter0,
                     const unsigned int nonce[3]) {
    size_t blocks = n / 64;
    size_t bper = blocks / nthreads;
    for (int i = 0; i < nthreads; i++) {
        pthread_mutex_lock(&workers[i].mu);
        workers[i].pt = pt; workers[i].ct = ct;
        workers[i].off = (size_t)i * bper * 64;
        size_t bend = (i == nthreads - 1) ? blocks : (size_t)(i + 1) * bper;
        workers[i].len = bend * 64 - workers[i].off;
        memcpy(workers[i].key, key, 32);
        workers[i].counter0 = counter0;
        workers[i].nonce[0] = nonce[0];
        workers[i].nonce[1] = nonce[1];
        workers[i].nonce[2] = nonce[2];
        workers[i].ready = 0;
        workers[i].cmd = 1;
        pthread_cond_signal(&workers[i].cv);
        pthread_mutex_unlock(&workers[i].mu);
    }
    for (int i = 0; i < nthreads; i++) {
        pthread_mutex_lock(&workers[i].mu);
        while (!workers[i].ready) pthread_cond_wait(&workers[i].cv, &workers[i].mu);
        pthread_mutex_unlock(&workers[i].mu);
    }
}

static void pad16(void *ctx, size_t n) {
    static const unsigned char zeros[16] = {0};
    size_t rem = n & 15;
    if (rem) Poly1305_Update(ctx, zeros, 16 - rem);
}
static void le64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (unsigned char)(v >> (8 * i));
}

static void aead_parallel(const unsigned char keyb[32], const unsigned char nonce[12],
                          const unsigned char *aad, size_t aad_len,
                          const unsigned char *pt, unsigned char *ct, size_t pt_len,
                          unsigned char tag[16], void *pctx) {
    unsigned int key[8];
    memcpy(key, keyb, 32);
    unsigned int nonce_w[3];
    memcpy(nonce_w, nonce, 12);

    unsigned char poly_key_block[64];
    unsigned char zeros64[64] = {0};
    unsigned int counter[4] = {0, nonce_w[0], nonce_w[1], nonce_w[2]};
    ChaCha20_ctr32(poly_key_block, zeros64, 64, key, counter);

    /* parallel encrypt starting at counter 1. Assume pt_len multiple of 64 for bench; handle tail on main. */
    size_t main_len = pt_len & ~(size_t)63;
    size_t tail = pt_len - main_len;
    if (main_len) pool_run((unsigned char*)pt, ct, main_len, key, 1, nonce_w);
    if (tail) {
