int chacha20poly1305_seal(const unsigned char keyb[32], const unsigned char nonce[12],
                          const unsigned char *aad, size_t aad_len,
                          const unsigned char *pt, size_t pt_len,
                          unsigned char *ct, unsigned char tag[16], int nthreads) {
