    unsigned char zeros[64] = {0};
    unsigned int counter[4] = {0, nonce_w[0], nonce_w[1], nonce_w[2]};
    ChaCha20_ctr32(block0, zeros, 64, key, counter);

    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;

    size_t main_len = pt_len & ~(size_t)63;
    size_t tail = pt_len - main_len;

    if (nthreads == 1 || main_len < 64ull * (size_t)nthreads) {
        unsigned int ctr[4] = {1, nonce_w[0], nonce_w[1], nonce_w[2]};
        if (pt_len) ChaCha20_ctr32(ct, pt, pt_len, key, ctr);
    } else {
        pthread_t th[MAX_THREADS];
        job_t jobs[MAX_THREADS];
        size_t blocks = main_len / 64;
        size_t bper = blocks / (size_t)nthreads;
        int launched = 0;
        for (int i = 0; i < nthreads; i++) {
            size_t b0 = (size_t)i * bper;
            size_t b1 = (i == nthreads - 1) ? blocks : b0 + bper;
            jobs[i].pt = pt;
            jobs[i].ct = ct;
            jobs[i].off = b0 * 64;
            jobs[i].len = (b1 - b0) * 64;
            memcpy(jobs[i].key, key, 32);
            jobs[i].counter0 = 1;
            jobs[i].nonce[0] = nonce_w[0];
            jobs[i].nonce[1] = nonce_w[1];
            jobs[i].nonce[2] = nonce_w[2];
            if (pthread_create(&th[launched], NULL, worker, &jobs[i]) == 0) launched++;
            else worker(&jobs[i]);
        }
        for (int i = 0; i < launched; i++) pthread_join(th[i], NULL);
        if (tail) {
            unsigned int ctr[4] = {1u + (unsigned int)(main_len / 64), nonce_w[0], nonce_w[1], nonce_w[2]};
