extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define MAX_THREADS 8

typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv_work;
    pthread_cond_t cv_done;
    int cmd;          /* 0 idle, 1 work, 2 exit */
    int done;
    const unsigned char *pt;
    unsigned char *ct;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter0;
    unsigned int nonce[3];
    pthread_t th;
} worker_t;

static worker_t workers[MAX_THREADS];
static int pool_n = 0;
static int pool_inited = 0;
static pthread_once_t pool_once = PTHREAD_ONCE_INIT;

static void *worker_fn(void *arg) {
    worker_t *w = (worker_t *)arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0)
            pthread_cond_wait(&w->cv_work, &w->mu);
        if (w->cmd == 2) {
            pthread_mutex_unlock(&w->mu);
            return NULL;
        }
        const unsigned char *pt = w->pt;
        unsigned char *ct = w->ct;
        size_t off = w->off, len = w->len;
        unsigned int key[8];
        memcpy(key, w->key, 32);
        unsigned int ctr[4];
        ctr[0] = w->counter0 + (unsigned int)(off / 64);
        ctr[1] = w->nonce[0];
        ctr[2] = w->nonce[1];
        ctr[3] = w->nonce[2];
        pthread_mutex_unlock(&w->mu);

        ChaCha20_ctr32(ct + off, pt + off, len, key, ctr);

        pthread_mutex_lock(&w->mu);
        w->cmd = 0;
        w->done = 1;
        pthread_cond_signal(&w->cv_done);
    }
}

static void pool_init_fn(void) {
    int nt = 4;
    const char *e = getenv("CHACHA_THREADS");
    if (e && e[0]) {
        int v = atoi(e);
        if (v >= 1 && v <= MAX_THREADS) nt = v;
    }
    pool_n = nt;
    for (int i = 0; i < nt; i++) {
        pthread_mutex_init(&workers[i].mu, NULL);
        pthread_cond_init(&workers[i].cv_work, NULL);
        pthread_cond_init(&workers[i].cv_done, NULL);
        workers[i].cmd = 0;
        workers[i].done = 0;
        pthread_create(&workers[i].th, NULL, worker_fn, &workers[i]);
    }
    pool_inited = 1;
}

static void pool_encrypt(const unsigned char *pt, unsigned char *ct, size_t len,
                         const unsigned int key[8], unsigned int counter0,
                         const unsigned int nonce[3]) {
    pthread_once(&pool_once, pool_init_fn);
    int nt = pool_n;
    size_t blocks = len / 64;
    if (nt <= 1 || blocks < (size_t)nt * 4) {
        unsigned int ctr[4] = {counter0, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(ct, pt, len, key, ctr);
        return;
    }
    size_t bper = blocks / (size_t)nt;
    for (int i = 0; i < nt; i++) {
        size_t b0 = (size_t)i * bper;
        size_t b1 = (i == nt - 1) ? blocks : b0 + bper;
        pthread_mutex_lock(&workers[i].mu);
        workers[i].pt = pt;
        workers[i].ct = ct;
        workers[i].off = b0 * 64;
        workers[i].len = (b1 - b0) * 64;
        memcpy(workers[i].key, key, 32);
        workers[i].counter0 = counter0;
        workers[i].nonce[0] = nonce[0];
        workers[i].nonce[1] = nonce[1];
        workers[i].nonce[2] = nonce[2];
        workers[i].done = 0;
        workers[i].cmd = 1;
        pthread_cond_signal(&workers[i].cv_work);
        pthread_mutex_unlock(&workers[i].mu);
    }
    for (int i = 0; i < nt; i++) {
        pthread_mutex_lock(&workers[i].mu);
        while (!workers[i].done)
            pthread_cond_wait(&workers[i].cv_done, &workers[i].mu);
        pthread_mutex_unlock(&workers[i].mu);
    }
}

static void le64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (unsigned char)(v >> (8 * i));
}

int chacha20poly1305_seal(const unsigned char keyb[32], const unsigned char nonce[12],
                          const unsigned char *aad, size_t aad_len,
                          const unsigned char *pt, size_t pt_len,
                          unsigned char *ct, unsigned char tag[16]) {
    unsigned int key[8];
    memcpy(key, keyb, 32);
    unsigned int nonce_w[3];
    memcpy(nonce_w, nonce, 12);

    unsigned char block0[64];
    unsigned char zeros[64] = {0};
    unsigned int counter[4] = {0, nonce_w[0], nonce_w[1], nonce_w[2]};
    ChaCha20_ctr32(block0, zeros, 64, key, counter);

    size_t main_len = pt_len & ~(size_t)63;
    size_t tail = pt_len - main_len;
    if (main_len)
        pool_encrypt(pt, ct, main_len, key, 1, nonce_w);
    if (tail) {
        unsigned int ctr[4] = {1u + (unsigned int)(main_len / 64), nonce_w[0], nonce_w[1], nonce_w[2]};
        ChaCha20_ctr32(ct + main_len, pt + main_len, tail, key, ctr);
    }

    /* stack poly1305 ctx: OpenSSL size is 248; allocate a bit extra statically via malloc once */
    static __thread unsigned char pbuf[512];
    void *pctx = pbuf;
    Poly1305_Init(pctx, block0);
    if (aad && aad_len) Poly1305_Update(pctx, aad, aad_len);
    if (aad_len & 15) {
        unsigned char z[16] = {0};
        Poly1305_Update(pctx, z, 16 - (aad_len & 15));
    }
    if (pt_len) Poly1305_Update(pctx, ct, pt_len);
    if (pt_len & 15) {
        unsigned char z[16] = {0};
        Poly1305_Update(pctx, z, 16 - (pt_len & 15));
    }
    unsigned char lens[16];
    le64(lens, (uint64_t)aad_len);
    le64(lens + 8, (uint64_t)pt_len);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
    memset(block0, 0, 32);
    return 0;
}
